class EntitySearchView(View):
    template = "search.html"

    def __init__(self, db: DB, search: str, user: User):
        super().__init__(db, user)

        self.search = search

    @json_view
    def get_results(self):
        return self.db.get_entity_search_results(self.search)

    def render(self):
        search_results = []
        for search_result in search_entities(self.db, self.search):
            if search_result is None:
                continue
            elif isinstance(search_result, Entity):
                search_results.append({
                    'type': 'entity',
                    'entity': search_result.to_dict(),
                })
            else:
                search_results.append(search_result.to_dict())

        return {
           'search': self.search,
           'search_results': search_results,
        }


class SearchResultView(JsonView):
    def __init__(self, db: DB, entity_id: int, user: User):
        super().__init__(db, user)

        self.entity_id = entity_id

    def _get_search_result(self) -> SearchResult:
        return search_entities(self.db, self.entity_id)[0]

    def get(self):
        search_result = self._get_search_result()
        return self.render(search_result)
